const body = $input.first().json.body;

const description = (body.description || '').trim();
const manualKeywordsRaw = (body.manual_keywords || '').trim();
const locationCode = parseInt(body.location) || 2356;
const languageCode = body.language || 'en';
const depth = body.depth || 'minimal';

const locationMap = {
  2356: 'India', 2840: 'United States', 2826: 'United Kingdom',
  2124: 'Canada', 2036: 'Australia', 2276: 'Germany',
  2250: 'France', 2152: 'Japan', 2156: 'Brazil',
  2484: 'Singapore', 2704: 'United Arab Emirates'
};

return {
  description, locationCode, locationName: locationMap[locationCode] || ('Code ' + locationCode),
  languageCode, depth,
  manualKeywords: manualKeywordsRaw.split(',').map(function(k) { return k.trim().toLowerCase(); }).filter(function(k) { return k; })
};

parameters.jsonBody:
{
  "model": "google/gemini-2.0-flash-001",
  "messages": [{
    "role": "user",
    "content": "You are an expert SEO and audience research analyst. Given a description of a target audience, generate 20 specific, actionable Google search keywords that members of this audience would actually type into Google. Rules: Return ONLY a JSON array of strings. No explanation, no markdown. Each keyword 1-5 words. Cover all intents.\n\nAudience description: {{ $json.description }}\n\nReturn: [\"keyword1\", \"keyword2\", ...]"
  }],
  "max_tokens": 500, "temperature": 0.7
}

