var prevInput = $('Code - Parse Form Input').first().json;
var openRouterBody = $input.first().json;
var choices = openRouterBody.choices || [];
var aiText = (choices[0] || {}).message ? (choices[0].message.content || '') : '';

var aiKeywords = [];
try {
  var text = aiText.trim();
  if (text.startsWith('```')) { text = text.split('\n').slice(1).join('\n'); text = text.split('```')[0]; }
  aiKeywords = JSON.parse(text);
  if (!Array.isArray(aiKeywords)) aiKeywords = [];
} catch (e) { aiKeywords = []; }

var manualKws = prevInput.manualKeywords || [];
var allKws = aiKeywords.map(function(k) { return k.toLowerCase().trim(); });
manualKws.forEach(function(k) { if (allKws.indexOf(k.toLowerCase().trim()) === -1) allKws.push(k.toLowerCase().trim()); });

return { description: prevInput.description, locationCode: prevInput.locationCode, locationName: prevInput.locationName, languageCode: prevInput.languageCode, depth: prevInput.depth, keywords: allKws };

var data = $input.first().json;
var kws = data.keywords || [];
var loc = data.locationCode;
var lang = data.languageCode;
var depth = data.depth;

var basicAuth = 'Basic ' + Buffer.from('abhishekbolarshetty@gmail.com:6aa69ca0a4bf8188').toString('base64');
var authHeaders = { Authorization: basicAuth, 'Content-Type': 'application/json' };

async function callDFSEO(url, body) {
  return await this.helpers.httpRequest({
    method: 'POST', url: url, body: body, headers: authHeaders
  });
}

var volBody = [{ keywords: kws.slice(0, 800), location_code: loc, language_code: lang }];
var volResult = {};
try { volResult = await callDFSEO('https://api.dataforseo.com/v3/keywords_data/google_ads/search_volume/live', volBody); }
catch (e) { console.error('Volume error: ' + e.message); volResult = { tasks: [{ result: [] }] }; }

var intentResult = { tasks: [{ result: [] }] };
if (depth !== 'minimal') {
  var intentBody = [{ keywords: kws.slice(0, 50), location_code: loc, language_code: lang }];
  try { intentResult = await callDFSEO('https://api.dataforseo.com/v3/dataforseo_labs/google/search_intent/live', intentBody); }
  catch (e) { console.error('Intent error: ' + e.message); }
}

var trendsResult = { tasks: [{ result: [] }] };
if (depth !== 'minimal') {
  var trendsBody = [{ keywords: kws.slice(0, 5), location_code: loc }];
  try { trendsResult = await callDFSEO('https://api.dataforseo.com/v3/keywords_data/google_trends/explore/live', trendsBody); }
  catch (e) { console.error('Trends error: ' + e.message); }
}

var demoResult = { tasks: [{ result: [] }] };
if (depth === 'full') {
  var demoBody = [{ keywords: kws.slice(0, 5), location_code: loc }];
  try { demoResult = await callDFSEO('https://api.dataforseo.com/v3/keywords_data/dataforseo_trends/demography/live', demoBody); }
  catch (e) { console.error('Demographics error: ' + e.message); }
}

var geoResult = { tasks: [{ result: [] }] };
if (depth === 'full') {
  var geoBody = [{ keywords: kws.slice(0, 5), location_code: loc }];
  try { geoResult = await callDFSEO('https://api.dataforseo.com/v3/keywords_data/dataforseo_trends/subregion_interests/live', geoBody); }
  catch (e) { console.error('Subregion error: ' + e.message); }
}

return { description: data.description, locationCode: loc, locationName: data.locationName, languageCode: lang, depth: depth, keywords: kws, volumeResult: volResult, intentResult: intentResult, trendsResult: trendsResult, demoResult: demoResult, geoResult: geoResult };

var all = $input.first().json;
var depth = all.depth || 'minimal';
var locationName = all.locationName || 'Unknown';
var description = all.description || '';

var volResult = ((all.volumeResult.tasks || [])[0] || {}).result || [];
var keywordsData = volResult.map(function(e) {
  return {
    keyword: (e.keyword || '').toLowerCase().trim(),
    search_volume: e.search_volume || 0,
    cpc: e.cpc || 0,
    competition: e.competition || 'LOW'
  };
});

var intentMap = {};
var iResult = ((all.intentResult.tasks || [])[0] || {}).result || [];
for (var i = 0; i < iResult.length; i++) {
  var item = iResult[i];
  var items = item.items || [];
  for (var j = 0; j < items.length; j++) {
    var si = items[j];
    var kw = (si.keyword || '').toLowerCase().trim();
    if (kw) { intentMap[kw] = (si.keyword_intent || {}).label || 'informational'; }
  }
}

var trendMap = {};
var tResult = ((all.trendsResult.tasks || [])[0] || {}).result || [];
for (var i = 0; i < tResult.length; i++) {
  var item = tResult[i];
  var tItems = item.items || [];
  for (var j = 0; j < tItems.length; j++) {
    var ti = tItems[j];
    var kwList = ti.keywords || [];
    var dataArr = ti.data || [];
    var vals = [];
    for (var g = 0; g < dataArr.length; g++) {
      var v = (dataArr[g].values || [])[0];
      if (v !== null && v !== undefined) vals.push(v);
    }
    var dir = 'unknown';
    if (vals.length >= 4) {
      var recent = 0, priorSum = 0;
      for (var k = vals.length - 3; k < vals.length; k++) recent += vals[k];
      for (var k = 0; k < vals.length - 3; k++) priorSum += vals[k];
      var prior = priorSum / (vals.length - 3);
      if (prior === 0) dir = 'growing';
      else {
        var d = (recent / 3 - prior) / prior * 100;
        if (d > 10) dir = 'growing';
        else if (d < -10) dir = 'declining';
        else dir = 'stable';
      }
    }
    for (var k = 0; k < kwList.length; k++) trendMap[(kwList[k] || '').toLowerCase().trim()] = dir;
  }
}

var ageAgg = {}, genderAgg = { male: 0, female: 0 };
var demoCount = 0;
var dResult = ((all.demoResult.tasks || [])[0] || {}).result || [];
for (var i = 0; i < dResult.length; i++) {
  var item = dResult[i];
  var dItems = item.items || [];
  for (var j = 0; j < dItems.length; j++) {
    var si = dItems[j];
    var dem = si.demography || {};
    var ageList = dem.age || [];
    for (var a = 0; a < ageList.length; a++) {
      var ae = ageList[a];
      var vals = ae.values || [];
      for (var v = 0; v < vals.length; v++) {
        if (vals[v].type) ageAgg[vals[v].type] = (ageAgg[vals[v].type] || 0) + (vals[v].value || 0);
      }
    }
    var genList = dem.gender || [];
    for (var g = 0; g < genList.length; g++) {
      var ge = genList[g];
      var vals = ge.values || [];
      for (var v = 0; v < vals.length; v++) {
        var t = (vals[v].type || '').toLowerCase();
        if (t === 'male' || t === 'female') genderAgg[t] = genderAgg[t] + (vals[v].value || 0);
      }
    }
    demoCount++;
  }
}
var demoAge = {};
if (demoCount > 0) {
  var ageKeys = Object.keys(ageAgg);
  var ageTotal = 0;
  for (var i = 0; i < ageKeys.length; i++) ageTotal += ageAgg[ageKeys[i]];
  if (ageTotal === 0) ageTotal = 1;
  for (var i = 0; i < ageKeys.length; i++) demoAge[ageKeys[i]] = Math.round(ageAgg[ageKeys[i]] / ageTotal * 1000) / 10;
}
var demoGender = { male: 50, female: 50 };
if (demoCount > 0 && (genderAgg.male + genderAgg.female) > 0) {
  var genTotal = genderAgg.male + genderAgg.female;
  demoGender.male = Math.round(genderAgg.male / genTotal * 1000) / 10;
  demoGender.female = Math.round(genderAgg.female / genTotal * 1000) / 10;
}

var geoMap = {};
var gResult = ((all.geoResult.tasks || [])[0] || {}).result || [];
for (var i = 0; i < gResult.length; i++) {
  var item = gResult[i];
  var gItems = item.items || [];
  for (var j = 0; j < gItems.length; j++) {
    var si = gItems[j];
    var interests = si.interests || [];
    for (var ie = 0; ie < interests.length; ie++) {
      var vals = interests[ie].values || [];
      for (var v = 0; v < vals.length; v++) {
        var n = (vals[v].geo_name || '').trim();
        if (n) geoMap[n] = (geoMap[n] || 0) + (vals[v].value || 0);
      }
    }
  }
}

var DEDUP = 0.65, COVERAGE = 1.4;
var totalVolume = 0;
for (var i = 0; i < keywordsData.length; i++) totalVolume += (keywordsData[i].search_volume || 0);
var uniqueAudience = Math.floor(totalVolume * DEDUP);
var tam = Math.floor(uniqueAudience * COVERAGE);

var intentVol = {};
for (var i = 0; i < keywordsData.length; i++) {
  var intent = intentMap[keywordsData[i].keyword] || 'informational';
  intentVol[intent] = (intentVol[intent] || 0) + (keywordsData[i].search_volume || 0);
}
var iKeys = Object.keys(intentVol);
var iTotal = 0;
for (var i = 0; i < iKeys.length; i++) iTotal += intentVol[iKeys[i]];
if (iTotal === 0) iTotal = 1;
var intentSegments = [];
for (var i = 0; i < iKeys.length; i++) {
  intentSegments.push({ label: iKeys[i], volume: intentVol[iKeys[i]], pct: Math.round(intentVol[iKeys[i]] / iTotal * 1000) / 10 });
}
intentSegments.sort(function(a, b) { return b.volume - a.volume; });

var commercialPct = 0;
for (var i = 0; i < intentSegments.length; i++) {
  if (intentSegments[i].label === 'commercial') commercialPct = intentSegments[i].pct || 0;
}
var commercialAudience = Math.floor(uniqueAudience * commercialPct / 100);
var cpcs = [];
for (var i = 0; i < keywordsData.length; i++) { if ((keywordsData[i].cpc || 0) > 0) cpcs.push(keywordsData[i].cpc); }
var avgCpc = 0;
if (cpcs.length > 0) {
  var cpcSum = 0;
  for (var i = 0; i < cpcs.length; i++) cpcSum += cpcs[i];
  avgCpc = Math.round(cpcSum / cpcs.length * 100) / 100;
}

var levels = [];
for (var i = 0; i < keywordsData.length; i++) levels.push((keywordsData[i].competition || 'LOW').toUpperCase());
var highCount = 0, medCount = 0;
for (var i = 0; i < levels.length; i++) {
  if (levels[i] === 'HIGH') highCount++;
  if (levels[i] === 'MEDIUM') medCount++;
}
var competitionLevel = 'LOW';
if (highCount > levels.length * 0.4) competitionLevel = 'HIGH';
else if (medCount > levels.length * 0.5) competitionLevel = 'MEDIUM';

var trendCounts = { growing: 0, stable: 0, declining: 0 };
var trendKeys = Object.keys(trendMap);
for (var i = 0; i < trendKeys.length; i++) {
  var v = trendMap[trendKeys[i]];
  if (trendCounts[v] !== undefined) trendCounts[v]++;
}

var demoSegments = [];
var ageKeys = Object.keys(demoAge);
var genKeys = Object.keys(demoGender);
for (var i = 0; i < ageKeys.length; i++) {
  for (var j = 0; j < genKeys.length; j++) {
    demoSegments.push({
      age_group: ageKeys[i],
      gender: genKeys[j],
      audience_size: Math.floor(uniqueAudience * demoAge[ageKeys[i]] / 100 * demoGender[genKeys[j]] / 100)
    });
  }
}

var geoEntries = Object.keys(geoMap).map(function(k) { return [k, geoMap[k]]; });
geoEntries.sort(function(a, b) { return b[1] - a[1]; });
geoEntries = geoEntries.slice(0, 10);
var geoTotal = 0;
for (var i = 0; i < geoEntries.length; i++) geoTotal += geoEntries[i][1];
if (geoTotal === 0) geoTotal = 1;
var geoWithSize = [];
for (var i = 0; i < geoEntries.length; i++) {
  geoWithSize.push({
    region: geoEntries[i][0],
    interest: geoEntries[i][1],
    audience_size: Math.floor(uniqueAudience * geoEntries[i][1] / geoTotal)
  });
}

function F(n) { return n.toLocaleString('en-US'); }
function C(n) { return '$' + n.toFixed(2); }
function U(s) { return s.charAt(0).toUpperCase() + s.slice(1); }
var rid = Date.now().toString(36);

var H = '<!DOCTYPE html>\n<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>AudienceScope - Report</title>';
H += '<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>';
H += '<link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;500;600;700;800;900" rel="stylesheet">';
H += '<style>:root{--brand-navy:#1f3a68;--brand-sky:#1fb1f5;--brand-yellow:#ffdc27;--bg:#f8f8f6;--card:#fff;--text:#1c1b1b;--text-mute:#7d7d7d;--border:#e6e6e6;--accent:#1fb1f5;--sky-700:#0b87c0;--shadow-sm:0 2px 6px rgba(14,31,58,.06);--ease-out:cubic-bezier(.23,1,.32,1)}';
H += '*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}html{-webkit-font-smoothing:antialiased}body{font-family:Montserrat,system-ui,sans-serif;background:var(--bg);color:var(--text);line-height:1.55;font-size:14px}';
H += '.container{max-width:860px;margin:0 auto;padding:36px 28px 60px}';
H += '.report-header{margin-bottom:20px}h1{font-size:26px;font-weight:800;color:var(--brand-navy);letter-spacing:-.02em}.header-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}';
H += '.back-link{font-size:11px;font-weight:600;color:var(--text-mute);text-decoration:none;text-transform:uppercase;letter-spacing:.04em}';
H += '.audience-desc{font-size:14px;margin:6px 0;max-width:640px;line-height:1.6}.meta{color:var(--text-mute);font-size:12px}';
H += '.card-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}@media(max-width:720px){.card-grid{grid-template-columns:1fr 1fr}}';
H += '.card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:18px 16px;box-shadow:var(--shadow-sm);text-align:center}';
H += '.card-label{display:block;font-size:12px;font-weight:700;color:var(--text-mute);text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px}';
H += '.card-value{display:block;font-size:22px;font-weight:800;color:var(--brand-navy);letter-spacing:-.01em}';
H += '.card.highlight .card-value{color:var(--sky-700)}.card-sub{display:block;font-size:12px;color:var(--text-mute);margin-top:4px}';
H += '.section-row{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:20px}@media(max-width:540px){.section-row{grid-template-columns:1fr}}';
H += 'section{margin-bottom:24px;animation:card-in .2s var(--ease-out) both}section h2{font-size:12px;font-weight:700;color:var(--text-mute);text-transform:uppercase;letter-spacing:.08em;margin-bottom:12px}';
H += '.intent-row{display:flex;align-items:center;gap:10px;margin-bottom:10px}.intent-name{width:110px;font-size:13px;font-weight:600;text-transform:capitalize}';
H += '.bar-track{flex:1;height:10px;background:#eef2f6;border-radius:999px;overflow:hidden}.bar-fill{height:100%;border-radius:999px;animation:bar-grow .48s var(--ease-out) both}';
H += '.intent-informational{background:linear-gradient(90deg,#3b82f6,#1d4ed8)}.intent-commercial{background:linear-gradient(90deg,#f59e0b,#b45309)}';
H += '.intent-transactional{background:linear-gradient(90deg,#10b981,#047857)}.intent-navigational{background:linear-gradient(90deg,#8b5cf6,#6d28d9)}';
H += '.intent-stats{font-size:12px;font-weight:600;color:var(--text-mute);min-width:120px;text-align:right}';
H += '.trend-row{display:flex;gap:10px;flex-wrap:wrap}.trend-chip{display:inline-flex;padding:4px 12px;border-radius:999px;font-size:12px;font-weight:600}';
H += '.trend-chip.growing{background:#d1fae5;color:#065f46}.trend-chip.stable{background:#eef2f6;color:#4a5568}.trend-chip.declining{background:#fee2e2;color:#991b1b}';
H += '.data-table{width:100%;border-collapse:collapse;font-size:13px}.data-table th{text-align:left;padding:9px 12px;font-size:11.5px;font-weight:700;color:var(--text-mute);text-transform:uppercase;letter-spacing:.05em;background:#f8fafc;border-bottom:2px solid var(--border)}';
H += '.data-table td{padding:9px 12px;border-bottom:1px solid var(--border)}.data-table tbody tr:hover td{background:#f8fbff}';
H += '.geo-row{display:flex;align-items:center;gap:10px;margin-bottom:8px}.geo-name{width:140px;font-size:13px;font-weight:500}';
H += '.geo-fill{background:linear-gradient(90deg,var(--accent),var(--sky-700))}.geo-size{font-size:12px;font-weight:600;color:var(--text-mute);min-width:90px;text-align:right}';
H += '.empty{color:var(--text-mute);font-style:italic;padding:8px 0;font-size:13px}';
H += '.competition-LOW{color:#0b87c0}.competition-MEDIUM{color:#d29922}.competition-HIGH{color:#b91c1c}';
H += '@keyframes card-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}@keyframes bar-grow{from{width:0%!important}}';
H += '.card-grid .card{animation:card-in .22s var(--ease-out) both}.card-grid .card:nth-child(1){animation-delay:0ms}.card-grid .card:nth-child(2){animation-delay:30ms}.card-grid .card:nth-child(3){animation-delay:60ms}.card-grid .card:nth-child(4){animation-delay:90ms}';
H += 'section:nth-child(3){animation-delay:40ms}section:nth-child(4){animation-delay:70ms}section:nth-child(5){animation-delay:.1s}section:nth-child(6){animation-delay:.13s}';
H += '@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;animation-delay:0ms!important}}</style></head><body><div class="container">';

H += '<header class="report-header"><div class="header-top"><a href="#" class="back-link">Back</a><div></div></div>';
H += '<h1>Audience Research Report</h1>';
if (description) H += '<p class="audience-desc">Audience: ' + description + '</p>';
H += '<p class="meta">Location: ' + locationName + ' - Depth: ' + U(depth) + ' - Report: ' + rid + '</p></header><main>';

H += '<div class="card-grid">';
H += '<div class="card highlight"><span class="card-label">Monthly Volume</span><span class="card-value">' + F(totalVolume) + '</span></div>';
H += '<div class="card"><span class="card-label">Unique Audience</span><span class="card-value">' + F(uniqueAudience) + '</span></div>';
H += '<div class="card"><span class="card-label">TAM</span><span class="card-value">' + F(tam) + '</span></div>';
H += '<div class="card"><span class="card-label">Avg CPC</span><span class="card-value">' + C(avgCpc) + '</span></div>';
H += '</div>';

H += '<div class="section-row">';
H += '<div class="card"><span class="card-label">Competition</span><span class="card-value competition-' + competitionLevel + '">' + competitionLevel + '</span></div>';
H += '<div class="card"><span class="card-label">Commercial Audience</span><span class="card-value">' + F(commercialAudience) + '</span><span class="card-sub">Avg CPC: ' + C(avgCpc) + '</span></div>';
H += '</div>';

if (depth !== 'minimal') {
  H += '<section><h2>Search Intent Breakdown</h2><div class="intent-bars">';
  for (var i = 0; i < intentSegments.length; i++) {
    var s = intentSegments[i];
    H += '<div class="intent-row"><span class="intent-name">' + U(s.label) + '</span><div class="bar-track"><div class="bar-fill intent-' + s.label + '" style="width:' + s.pct + '%"></div></div><span class="intent-stats">' + F(s.volume) + ' (' + s.pct + '%)</span></div>';
  }
  H += '</div></section>';
  H += '<section><h2>Trend Direction</h2><div class="trend-row">';
  H += '<span class="trend-chip growing">Growing: ' + trendCounts.growing + '</span>';
  H += '<span class="trend-chip stable">Stable: ' + trendCounts.stable + '</span>';
  H += '<span class="trend-chip declining">Declining: ' + trendCounts.declining + '</span>';
  H += '</div></section>';
}

if (depth === 'full') {
  H += '<section><h2>Demographics</h2>';
  if (demoSegments.length > 0) {
    H += '<table class="data-table"><thead><tr><th>Age Group</th><th>Gender</th><th>Audience Size</th></tr></thead><tbody>';
    for (var i = 0; i < demoSegments.length; i++) {
      var d = demoSegments[i];
      H += '<tr><td>' + d.age_group + '</td><td>' + U(d.gender) + '</td><td>' + F(d.audience_size) + '</td></tr>';
    }
    H += '</tbody></table>';
  } else { H += '<p class="empty">No demographic data available.</p>'; }
  H += '</section>';

  H += '<section><h2>Geographic Distribution</h2>';
  if (geoWithSize.length > 0) {
    H += '<div class="geo-bars">';
    var mI = geoWithSize[0].interest || 1;
    for (var i = 0; i < geoWithSize.length; i++) {
      var g = geoWithSize[i];
      H += '<div class="geo-row"><span class="geo-name">' + g.region + '</span><div class="bar-track"><div class="bar-fill geo-fill" style="width:' + Math.floor(g.interest / mI * 100) + '%"></div></div><span class="geo-size">' + F(g.audience_size) + '</span></div>';
    }
    H += '</div>';
  } else { H += '<p class="empty">No geographic data available.</p>'; }
  H += '</section>';
}

H += '</main></div></body></html>';

return { html: H, tam: tam, totalVolume: totalVolume, uniqueAudience: uniqueAudience, avgCpc: avgCpc, depth: depth, reportId: rid };
